#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_radius;
uniform float amzp_falloff1;
uniform float amzp_falloff2;
uniform float amzp_speed;
uniform float amzp_progress;
uniform float amzp_angle;
uniform float amzp_noiseAmt;
uniform float amzp_blendMode;
uniform float amzp_alphab;

    float4 sample(float2 uv){ return amzTexture(0, uv); }
    float rnd(float2 p){ return fract(sin(dot(p, float2(12.9898,78.233))) * 43758.5453); }

    float3 rgb2hsv(float3 c){
      float4 k = float4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
      float4 p = mix(float4(c.bg, k.wz), float4(c.gb, k.xy), step(c.b, c.g));
      float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));
      float d = q.x - min(q.w, q.y);
      float e = 1.0e-10;
      return float3(abs(q.z + (q.w - q.y) / (6.0*d + e)), d / (q.x + e), q.x);
    }
    float3 hsv2rgb(float3 c){
      float4 k = float4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
      float3 p = abs(fract(c.xxx + k.xyz) * 6.0 - k.www);
      return c.z * mix(k.xxx, clamp(p - k.xxx, 0.0, 1.0), c.y);
    }

    float3 screenBlend(float3 a, float3 b){ return 1.0 - (1.0 - a) * (1.0 - b); }

    void amzRender(){
      float2 uv = amzScreenNorm();
      float2 res = screen.zw;
      float aspect = res.x / res.y;

      float a = radians(amzp_angle) + amzp_progress * 6.28318530718 + time * amzp_speed;
      float2 center = float2(0.5, 0.5);
      float2 pos1 = center + float2(cos(a), sin(a)) * amzp_radius;
      float2 pos2 = center + float2(cos(a + 3.14159265359), sin(a + 3.14159265359)) * amzp_radius;

      float2 uvA = uv * float2(aspect, 1.0);
      float2 p1A = pos1 * float2(aspect, 1.0);
      float2 p2A = pos2 * float2(aspect, 1.0);

      float d1 = distance(uvA, p1A);
      float d2 = distance(uvA, p2A);

      float s1 = exp(-d1 * amzp_falloff1);
      float s2 = exp(-d2 * amzp_falloff2);

      float3 c1 = amzp_color1.rgb * s1;
      float3 c2 = amzp_color2.rgb * s2;
      float3 grad = clamp(c1 + c2, 0.0, 1.0);

      float n = rnd(uv);
      grad += n * amzp_noiseAmt;

      float3 base = sample(uv).rgb;
      float3 comp;
      int bm = int(int(amzp_blendMode));
      if(bm == 0){
        comp = grad;
      } else if(bm == 1){
        comp = base * grad;
      } else if(bm == 2){
        comp = screenBlend(base, grad);
      } else if(bm == 3){
        comp = mix(2.0 * base * grad, 1.0 - 2.0 * (1.0 - base) * (1.0 - grad), step(0.5, base));
      } else if(bm == 4){
        float3 hb = rgb2hsv(base);
        float3 hg = rgb2hsv(grad);
        comp = hsv2rgb(float3(hg.x, hg.y, hb.z));
      } else if(bm == 5 || bm == 13){
        comp = max(base, grad);
      } else if(bm == 6){
        comp = clamp(base / max(1.0 - grad, 1e-6), 0.0, 1.0);
      } else if(bm == 7){
        comp = clamp(1.0 - (1.0 - base) / max(grad, 1e-6), 0.0, 1.0);
      } else if(bm == 8){
        comp = clamp(base + grad, 0.0, 1.0);
      } else if(bm == 9){
        comp = clamp(base + grad - 1.0, 0.0, 1.0);
      } else if(bm == 10){
        comp = clamp(base + 2.0 * grad - 1.0, 0.0, 1.0);
      } else if(bm == 11 || bm == 12){
        comp = min(base, grad);
      } else if(bm == 14){
        comp = clamp((1.0 - 2.0 * grad) * base * base + 2.0 * grad * base, 0.0, 1.0);
      } else if(bm == 15){
        comp = mix(2.0 * base * grad, 1.0 - 2.0 * (1.0 - base) * (1.0 - grad), step(0.5, grad));
      } else if(bm == 16){
        comp = mix(2.0 * base * grad, 1.0 - 2.0 * (1.0 - base) * (1.0 - grad), step(0.5, grad));
      } else if(bm == 17){
        float3 hb = rgb2hsv(base);
        float3 hg = rgb2hsv(grad);
        comp = hsv2rgb(float3(hg.x, hb.y, hb.z));
      } else if(bm == 18){
        comp = abs(base - grad);
      } else if(bm == 19){
        float3 hb = rgb2hsv(base);
        float3 hg = rgb2hsv(grad);
        comp = hsv2rgb(float3(hb.x, hb.y, hg.z));
      } else if(bm == 20){
        float3 hb = rgb2hsv(base);
        float3 hg = rgb2hsv(grad);
        comp = hsv2rgb(float3(hb.x, hg.y, hb.z));
      } else if(bm == 21){
        float3 low = clamp(1.0 - (1.0 - base) / max(2.0 * grad, 1e-6), 0.0, 1.0);
        float3 high = clamp(base / max(2.0 * (1.0 - grad), 1e-6), 0.0, 1.0);
        comp = mix(low, high, step(0.5, grad));
      } else if(bm == 22){
        comp = mix(min(base, 2.0 * grad), max(base, 2.0 * grad - 1.0), step(0.5, grad));
      } else if(bm == 23){
        comp = clamp(base / max(grad, 1e-6), 0.0, 1.0);
      } else if(bm == 24){
        comp = clamp(base - grad, 0.0, 1.0);
      } else {
        comp = screenBlend(base, grad);
      }

      float3 outc = mix(base, comp, amzp_alphab);
      amzOutput = float4(outc, 1.0);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

